class Solution {
    struct TupleHash {
        size_t operator()(const tuple<int,int,int>& t) const {
            size_t seed = 0;
            seed ^= hash<int>()(get<0>(t)) + 0x9e3779b9 + (seed << 6) + (seed >> 2);
            seed ^= hash<int>()(get<1>(t)) + 0x9e3779b9 + (seed << 6) + (seed >> 2);
            seed ^= hash<int>()(get<2>(t)) + 0x9e3779b9 + (seed << 6) + (seed >> 2);
            return seed;
        }
    };
    unordered_map<tuple<int,int,int>, int, TupleHash> idMap;
    unordered_map<int, int> cnt;
    unordered_map<TreeNode*, int> nodeId;
    unordered_set<int> added;
    vector<TreeNode*> res;

    int dfs(TreeNode* node) {
        if (!node) return 0;
        int left = dfs(node->left);
        int right = dfs(node->right);
        tuple<int,int,int> key(node->val, left, right);
        int id;
        auto it = idMap.find(key);
        if (it == idMap.end()) {
            id = (int)idMap.size() + 1;
            idMap[key] = id;
        } else {
            id = it->second;
        }
        cnt[id]++;
        nodeId[node] = id;
        return id;
    }

    void collect(TreeNode* node) {
        if (!node) return;
        int id = nodeId[node];
        if (cnt[id] >= 2 && added.find(id) == added.end()) {
            added.insert(id);
            res.push_back(node);
        }
        collect(node->left);
        collect(node->right);
    }
public:
    vector<TreeNode*> findDuplicateSubtrees(TreeNode* root) {
        idMap.clear();
        cnt.clear();
        nodeId.clear();
        added.clear();
        res.clear();
        dfs(root);
        collect(root);
        return res;
    }
};
